function toggleCompList(id){
  const el=document.getElementById(id);
  if(el)el.style.display=el.style.display==='none'?'block':'none';
}

function buildCompTable(list,showCity){
  if(!list||!list.length)return `<div style="font-size:11px;color:var(--g3);padding:8px 0">Sin competidores registrados</div>`;
  const rows=list.map(e=>`<tr>
    <td style="padding:4px 6px;font-size:11px">${e.n}</td>
    ${showCity?`<td style="padding:4px 6px;font-size:11px;color:var(--g3)">${e.ciu||'—'}</td>`:''}
    <td style="padding:4px 6px;text-align:right;font-size:11px">${e.tA!=null?e.tA:'—'}</td>
    <td style="padding:4px 6px;text-align:right;font-size:11px">${e.tB!=null?e.tB:'—'}</td>
    <td style="padding:4px 6px;text-align:right;font-size:11px;font-weight:600">${e.tot||'—'}</td>
  </tr>`).join('');
  return `<table style="width:100%;border-collapse:collapse;margin-top:8px">
    <thead><tr style="border-bottom:1px solid var(--g1)">
      <th style="padding:4px 6px;text-align:left;font-size:10px;color:var(--g3)">Institución</th>
      ${showCity?'<th style="padding:4px 6px;text-align:left;font-size:10px;color:var(--g3)">Ciudad</th>':''}
      <th style="padding:4px 6px;text-align:right;font-size:10px;color:var(--g3)">Prom A</th>
      <th style="padding:4px 6px;text-align:right;font-size:10px;color:var(--g3)">Prom B</th>
      <th style="padding:4px 6px;text-align:right;font-size:10px;color:var(--g3)">Total 21-24</th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table>`;
}
function calcMeta(prom,cupo,pe,hayDem,acreditado,nPeriodos){
  if(prom==null)return[null,'---'];
  if((nPeriodos??99)<2)return[Math.round(prom*1.15),'C0'];
  const base=Math.min(prom,cupo);
  const pct=acreditado?0.05:0.10;
  const hd=hayDem!=null?hayDem:true;
  const dC=prom-cupo,dP=prom-pe;
  if(Math.abs(dC)<=2)return[Math.round(cupo*(1+pct)),'C1'];
  if(Math.abs(dP)<=2&&hd)return[Math.min(Math.round(pe*1.50),cupo),'C2'];
  if(dP<0&&hd)return[Math.round(pe*1.10),'C3'];
  if(dP<0&&!hd)return[Math.round(prom*1.10),'C4'];
  const util=prom/cupo;
  if(util<0.50&&hd)return[Math.round(Math.min(prom*1.25,cupo*0.65)),'C6'];
  return[Math.round(base*1.10),'C5'];
}


const CM={
  C0:{c:'var(--c0)',p:'var(--c0p)',ico:'🆕',t:'Programa nuevo',txt:'Menos de 2 períodos válidos de historial. Meta = promedio disponible × 1.15.'},
  C1:{c:'var(--c1)',p:'var(--c1p)',ico:'🎯',t:'Cerca del cupo máximo',txt:'Opera cerca del límite MEN. Meta = cupo × 1.05 (acreditado) o cupo × 1.10.'},
  C2:{c:'var(--c2)',p:'var(--c2p)',ico:'📈',t:'Equilibrio + competencia activa',txt:'Promedio ronda el PE y hay demanda privada. Meta = mín(PE × 1.50, cupo).'},
  C3:{c:'var(--c3)',p:'var(--c3p)',ico:'⚡',t:'Bajo PE + competencia activa',txt:'No cubre costos pero el mercado existe. Meta aspiracional = PE × 1.10.'},
  C4:{c:'var(--c4)',p:'var(--c4p)',ico:'⚠️',t:'Bajo PE + UDES lidera',txt:'No cubre costos y UDES lidera el segmento. Meta = promedio × 1.10.'},
  C5:{c:'var(--c5)',p:'var(--c5p)',ico:'📊',t:'Sostenible + UDES lidera',txt:'Programa sostenible con alta utilización. Meta = mín(promedio, cupo) × 1.10.'},
  C6:{c:'var(--c6)',p:'var(--c6p)',ico:'🚀',t:'Capacidad disponible + mercado activo',txt:'Utiliza menos del 50% del cupo con demanda privada activa. Meta = mín(promedio × 1.25, cupo × 0.65).'},
  '---':{c:'var(--g3)',p:'var(--g1)',ico:'—',t:'Sin dato',txt:'Sin promedio histórico para este semestre.'},
};

const CAMPUS_METROS={
  'Bucaramanga':'Bucaramanga · Floridablanca · Girón · Piedecuesta',
  'Cúcuta':'Cúcuta · Villa del Rosario · Los Patios · El Zulia · San Cayetano · Puerto Santander',
  'Valledupar':'Valledupar · La Paz · San Diego · Manaure · Agustín Codazzi',
  'Bogotá':'Bogotá D.C.',
};

let sem='A';

function onCampus(){
  const c=document.getElementById('sc').value;
  const s=document.getElementById('sp');s.innerHTML='';
  ['Pregrado','Especialización','Maestría','Doctorado'].forEach(n=>{
    const g=D.filter(d=>d.campus===c&&d.nivel===n);if(!g.length)return;
    const og=document.createElement('optgroup');og.label=n+'s';
    g.forEach(d=>{const o=document.createElement('option');o.value=d.programa;o.textContent=d.programa;og.appendChild(o);});
    s.appendChild(og);
  });
  render();
}

function setSem(s){
  sem=s;
  document.getElementById('ba').className='sb'+(s==='A'?' on':'');
  document.getElementById('bb').className='sb'+(s==='B'?' on':'');
  render();
}

function toggleMarco(){
  document.getElementById('marr').classList.toggle('open');
  document.getElementById('mb').classList.toggle('open');
}

function render(){
  const c=document.getElementById('sc').value;
  const p=document.getElementById('sp').value;
  const d=D.find(x=>x.campus===c&&x.programa===p);
  if(!d){document.getElementById('out').innerHTML='';return;}

  const YEARS=['2019','2020','2021','2022','2023','2024','2025'];
  const excl=d.histExcluir||{};
  const nA=YEARS.filter(y=>{const v=d.hist[y]?.A;return v!=null&&v>0&&!(excl[y]?.includes('A'));}).length;
  const nB=YEARS.filter(y=>{const v=d.hist[y]?.B;return v!=null&&v>0&&!(excl[y]?.includes('B'));}).length;
  const pa=d.promA, pb=d.promB;
  const nPer=sem==='A'?nA:nB;
  const prom=sem==='A'?pa:pb;
  const hayDem=sem==='A'?d.hayDemandaA:d.hayDemandaB;
  let [meta,cond]=calcMeta(prom,d.cupo,d.pe,hayDem,d.acreditado,nPer);
  const pisoMEI=sem==='A'?(d.metaMEI_A??null):(d.metaMEI_B??null);
  if(pisoMEI!=null&&meta!=null&&meta<pisoMEI){meta=pisoMEI;}
  const compPriv=sem==='A'?d.prom_comp_A:d.prom_comp_B;
  const nPriv=d.n_ies||0;
  const compPub=sem==='A'?(d.pub_A||null):(d.pub_B||null);
  const nPub=d.n_pub||0;
  const C=CM[cond]||CM['---'];

  const totalMkt=(prom||0)+(compPriv||0);
  const pctU=!compPriv?100:(totalMkt>0?Math.round((prom||0)/totalMkt*100):null);
  const pctC=pctU!=null?100-pctU:null;
  const promPrivIes=(compPriv&&nPriv>0)?Math.round(compPriv/nPriv):null;
  const promPubIes=(compPub&&nPub>0)?Math.round(compPub/nPub):null;

  const dCupo=prom!=null?+(prom-d.cupo).toFixed(1):null;
  const dPE=prom!=null?+(prom-d.pe).toFixed(1):null;
  const sg=v=>v==null?'—':(v>=0?'▲ ':'▼ ')+Math.abs(v).toFixed(1);

  const allV=YEARS.map(y=>d.hist[y]?.[sem]).filter(v=>v!=null).map(Number);
  const maxV=Math.max(...allV,d.pe,meta||0,1);

  const bars=YEARS.map(y=>{
    const v=d.hist[y]?.[sem];
    const h=v!=null?Math.max(Math.round((Number(v)/maxV)*84),2):0;
    const clr=v!=null?C.c:'var(--g1)';
    return `<div class="bc">
      <span class="bv" style="color:${v!=null?C.c:'var(--g2)'}">${v!=null?v:''}</span>
      <div class="br" style="height:${h}px;background:${clr}"></div>
      <span class="byr" style="color:${y==='2025'?C.c:'var(--g3)'}">${y}</span>
    </div>`;
  }).join('');
  const peH=Math.round((d.pe/maxV)*84);
  const peBar=`<div class="bc"><span class="bv" style="color:var(--go)">${d.pe}</span><div class="br bpe" style="height:${peH}px"></div><span class="byr" style="color:var(--go)">PE</span></div>`;

  const alerta=meta!=null&&meta>d.cupo?`<div style="margin-top:10px;font-size:12px;background:#FEF3E2;border-left:3px solid var(--go);padding:8px 12px;border-radius:0 6px 6px 0;color:#7A4A00">⚠ Meta (${meta}) supera cupo MEN (${d.cupo}). Verificar con Vicerrectoría.</div>`:'';

  const condTxt=d.cupoAnual?'Cupo fijo anual por resolución MEN.':C.txt;
  const condTitle=d.cupoAnual?'📌 Cupo fijo anual (MEN)':cond+' · '+C.t;

  // IDs únicos para las listas expandibles
  const uid=(c+'_'+d.programa).replace(/[^a-zA-Z0-9]/g,'_').replace(/_+/g,'_');
  const idPriv='cl_priv_'+uid;
  const idPub ='cl_pub_'+uid;

  // Chip de demanda (solo IES privadas, igual que antes)
  const demChip=nPriv>0
    ?(hayDem
      ?`<span class="dem-chip" style="background:#E6F4EC;color:var(--c2)">✓ Hay demanda &nbsp;·&nbsp; ${nPriv} IES privada${nPriv>1?'s':''} en el área</span>`
      :`<span class="dem-chip" style="background:var(--azpp);color:var(--az)">↑ UDES lidera el segmento privado</span>`)
    :`<span class="dem-chip" style="background:var(--g1);color:var(--g3)">Sin competidores privados registrados</span>`;

  // Columna toggle button helper
  const iesBtn=(n,id)=>n>0
    ?`<button onclick="toggleCompList('${id}')" style="display:inline-flex;align-items:center;gap:4px;border:1px solid var(--g1);background:#fff;border-radius:20px;padding:3px 10px;font-size:12px;font-weight:700;cursor:pointer;color:var(--g4)">${n} IES ▾</button>`
    :`<span style="font-size:12px;color:var(--g2)">—</span>`;

  const mktHTML=`<div class="mkt-card">
    <div class="mkt-title">Análisis de mercado · sem. ${sem} · área metropolitana</div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:10px">
      <div style="background:var(--azpp);border-radius:8px;padding:12px 14px">
        <div style="font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--g3);margin-bottom:6px">UDES · prom. histórico</div>
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:32px;font-weight:800;color:var(--az);line-height:1">${prom!=null?prom:'—'}</div>
        <div style="font-size:11px;color:var(--g3);margin-top:4px">est. · cuota de mercado: ${pctU!=null?pctU+'%':'—'}</div>
      </div>
      <div style="background:var(--g0);border-radius:8px;padding:12px 14px">
        <div style="font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--g3);margin-bottom:6px">IES Privadas</div>
        ${iesBtn(nPriv,idPriv)}
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:28px;font-weight:800;color:var(--g4);line-height:1;margin-top:6px">${compPriv!=null?Math.round(compPriv):'—'}</div>
        <div style="font-size:11px;color:var(--g3);margin-top:2px">${promPrivIes?promPrivIes+' est./IES':'sin datos'}</div>
        <div id="${idPriv}" style="display:none">${buildCompTable(d.comp_priv||[],false)}</div>
      </div>
      <div style="background:var(--g0);border-radius:8px;padding:12px 14px">
        <div style="font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--g3);margin-bottom:6px">IES Públicas</div>
        ${iesBtn(nPub,idPub)}
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:28px;font-weight:800;color:var(--g4);line-height:1;margin-top:6px">${compPub!=null?Math.round(compPub):'—'}</div>
        <div style="font-size:11px;color:var(--g3);margin-top:2px">${promPubIes?promPubIes+' est./IES':'sin datos'}</div>
        <div id="${idPub}" style="display:none">${buildCompTable(d.comp_pub||[],true)}</div>
      </div>
    </div>
    ${demChip}
    <div style="font-size:10px;color:var(--g3);margin-top:8px;padding-top:6px;border-top:1px solid var(--g1)">
      Área de influencia: ${CAMPUS_METROS[c]||c}
    </div>
    ${(d.programas_equiv||[]).length>0?`<div style="font-size:10px;color:var(--g3);margin-top:4px"><span style="font-weight:600;color:var(--g4)">También considerados en la demanda:</span> ${(d.programas_equiv||[]).join(' · ')}</div>`:''}
  </div>`;

  const barInd=prom!=null&&(compPriv!=null||compPub!=null)
    ?`<div class="ind-bar"><div class="ind-fill-udes" style="width:${pctU||0}%;background:var(--az)"></div><div class="ind-fill-comp" style="width:${pctC||0}%"></div></div>`
    :`<div class="ind-bar"><div class="ind-fill-udes" style="width:${Math.min(Math.round((prom||0)/d.cupo*100),100)}%;background:var(--az)"></div></div>`;

  document.getElementById('out').innerHTML=`
<div class="hero">
  <div class="hero-head">
    <div class="hero-prog">${d.programa}</div>
    <div class="hero-pills">
      <span class="pill">${c}</span><span class="pill">${d.nivel}</span>
      <span class="pill">Cupo MEN: <b style="color:#fff">${d.cupo}</b></span>
      <span class="pill">PE: <b style="color:#fff">${d.pe} est.</b></span>
      ${d.acreditado?'<span class="pill pill-ac">★ Acreditado</span>':''}
    </div>
  </div>
  <div class="hero-body" style="border-top-color:${C.c}">
    <div class="meta-blk">
      <div class="meta-lbl">Meta · Sem. ${sem}</div>
      ${meta!=null?`<div class="meta-n" style="color:${C.c}">${meta}</div><div class="meta-unit">matriculados primer curso</div>`:`<div style="font-family:'Barlow Condensed',sans-serif;font-size:40px;color:var(--g3)">—</div>`}
      <div class="cond-banner" style="background:${C.p}">
        <span class="cond-icon">${d.cupoAnual?'📌':C.ico}</span>
        <div><div class="cond-title" style="color:${C.c}">${condTitle}</div><div class="cond-txt">${condTxt}</div></div>
      </div>${alerta}
    </div>
    <div class="ind-blk">
      <div class="ind-row">
        <span class="ind-label">Promedio histórico</span>
        <span class="ind-val" style="color:var(--az)">${prom!=null?prom:'—'}</span>
        <span class="ind-sub">sem. ${sem} · 2019–2025</span>
        ${barInd}
      </div>
      <div class="ind-row">
        <span class="ind-label">Meta propuesta</span>
        <span class="ind-val" style="color:${C.c}">${meta!=null?meta:'—'}</span>
        <span class="ind-sub">${dCupo!=null?sg(dCupo)+' vs cupo':''} ${dPE!=null?'· '+sg(dPE)+' vs PE':''}</span>
        <div class="ind-bar"><div class="ind-fill-udes" style="width:${Math.min(Math.round((meta||0)/d.cupo*100),100)}%;background:${C.c}"></div></div>
      </div>
    </div>
  </div>
</div>
${mktHTML}
<div class="hist">
  <div class="sec-lbl">Histórico matriculados · Sem. ${sem} · 2019–2025</div>
  <div class="bars">${bars}${peBar}</div>
  <div class="hist-line"></div>
  <div class="hist-leg">
    <span><div class="leg-dot" style="background:${C.c}"></div>Matriculados UDES</span>
    <span><div class="leg-pe"></div>PE = ${d.pe}</span>
    ${meta!=null?`<span><div class="leg-dot" style="background:${C.c};opacity:.4"></div>Meta: ${meta}</span>`:''}
  </div>
</div>`;
}



// Init
const camps=[...new Set(D.map(d=>d.campus))];
const sc=document.getElementById('sc');
camps.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;sc.appendChild(o);});
onCampus();


